INSERT INTO formularios_respuestas (formulario_id, datos, estado, created_at) SELECT f.id, '{"rol":"Fotógrafo","nombre_fot":"Álvaro — Gimnàstic de Tarragona","correo":"alvaroexca2007@gmail.com","lectura":true,"seguimiento":true,"edad":"18-25 años","provincia":"Tarragona","ideas":"1.\tAportar una mirada diferente a los partidos, dando importancia no solo al resultado, sino también al ambiente, el esfuerzo, los jugadores y todas las personas que hacen posible cada partido. Captar esos momentos que muchas veces pasan desapercibidos y que también forman parte de la historia de un equipo.\n2.\tCrear contenido fotográfico de partidos y torneos mostrando el fútbol desde dentro: detalles, emociones, vestuarios, calentamientos, celebraciones, tensión y momentos espontáneos, buscando que cada reportaje transmita lo que se vive alrededor del campo y no únicamente lo que ocurre durante los 90 minutos.","material":"Nikon d5300 / objetivos 70-300mm i Nikon d3300 / objetivo 18-55mm","exp_foto":"Sí","exp_foto_desc":"He realizado fotografía deportiva en diferentes torneos de la Costa Brava y Tarragona, además de cubrir partidos y entrenamientos de fútbol base del Nàstic, Reus y otros clubes de la provincia. He trabajado con categorías cadetes, juveniles y amateurs, realizando tanto cobertura de partidos como sesiones y contenido fotográfico para los equipos.","cubrir":"Sí","equipos":["Girona FC","Granada CF","CD Leganés","RCD Mallorca","Real Oviedo","Real Sociedad B","Athletic Club B","Atlético Madrileño","Real Madrid Castilla","Real Zaragoza"]}', 'revisada', '2026-09-25 17:34:02' FROM formularios f WHERE f.slug = 'formulario-de-incorporacion-elotrofutbol' AND NOT EXISTS (SELECT 1 FROM formularios_respuestas r WHERE r.formulario_id = f.id AND r.created_at = '2026-09-25 17:34:02');
